mapper.select:
select * from ( SELECT T1.ISSUE_AMT/10000 ISSUE_AMT,
,T2.IS_SEC_BOND
,T6.INT_TYPE AS rateType ,nvl(T8.YIELD, T6.RATE)*100 RATE ,T4.TYPE_4 ,T4.TYPE_5
,T4.TYPE_9 ,T4.TYPE_10 ,T4.TYPE_11 ,T4.TYPE_12
,T6.COEFFICIENT ,T6.SPREAD_RATE*100 SPREAD_RATE
,T6.BENCHMARK_ID as indexId ,T7.PARTY_TYPE2 ,T8.BASIS ,T9.PAY_CYCLE payCycle ,MST_CUSTOMER_INFO.CUSTOMER_NAME issuerName ,MST_CUSTOMER_INFO.CUSTOMER_ID issuer ,B.EXERCISE_DATE exerciseDate ,T2.IS_CITY_BOND isCityBond ,T2.IS_ISSUE_ASSET isIssueAsset ,T2.APPEAR_MARKET_ID appearMarketId ,T7.INDUSTRY industry ,T7.INDUSTRY2 industry2 FROM FIN_PRODUCT T1 LEFT JOIN MST_CUSTOMER_INFO ON MST_CUSTOMER_INFO.CUSTOMER_ID = T1.ISSUER LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T3 ON T3.CUSTOMER_ID = T1.ISSUER LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_INFO T5 ON T5.FINPROD_ID = T1.FINPROD_ID
AND T5.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T5.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T6 ON T6.CASH_ID = T5.CASH_ID AND T6.EFF_DATE = T1.VDATE left join (select FINPROD_ID, max(eff_date) as EFF_DATE from FIN_CASH_CALC_RULE group by FINPROD_ID ) tempT8 on T1.FINPROD_ID = tempT8.FINPROD_ID
LEFT JOIN FIN_CASH_CALC_RULE T8 ON T8.FINPROD_ID=tempT8.FINPROD_ID AND T8.EFF_DATE = tempT8.EFF_DATE and T8.CASH_ID = T5.CASH_ID LEFT JOIN MST_CUSTOMER_INFO_ADD T7 ON T7.CUSTOMER_ID = T3.CUSTOMER_ID LEFT JOIN FIN_CASH_PAY_RULE T9 ON T9.CASH_ID = T8.CASH_ID AND T8.EFF_DATE = T9.EFF_DATE LEFT JOIN (select A.FINPROD_ID,max(A.EXERCISE_DATE) EXERCISE_DATE from FIN_EXERCISE_PLAN A group by A.FINPROD_ID) B on T1.FINPROD_ID = B.FINPROD_ID) T
AND (T.FINPROD_MARKET_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%') or T.FINPROD_NAME like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%'))
AND T.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T.CCY = #{ccy,jdbcType=VARCHAR}
AND T.TYPE_4 in
#{item}
AND T.TYPE_5 = #{type5,jdbcType=VARCHAR}
AND T.TYPE_9 in
#{item}
AND T.TYPE_10 in
#{item}
AND T.TYPE_11 in
#{item}
AND T.rateType = #{rateType,jdbcType=VARCHAR}
AND T.COUPON_SPECIES = #{couponSpecies,jdbcType=VARCHAR}
AND T.VDATE >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND T.VDATE <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND T.MDATE >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND T.MDATE <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
AND T.ISSUER = #{issuer,jdbcType=VARCHAR}
AND T.ISISSUEASSET = #{isIssueAsset,jdbcType=VARCHAR}
AND (T.ISISSUEASSET = #{isIssueAsset,jdbcType=VARCHAR} OR T.ISISSUEASSET IS NULL)
and T.FINPROD_ID in ( select FINPROD_ID from ( select FINPROD_ID,min(TRADE_DATE) from TRD_PRODUCT_DEAL where TRADE_DATE = to_date(#{platDate,jdbcType=VARCHAR},'yyyy-mm-dd') and IS_OUT_TRADE = 'Y' and FINPROD_TYPE2 = 'F01' and IS_CANCEL = 'N' and TRADE_STATUS = '01' group by FINPROD_ID having min(TRADE_DATE) = to_date(#{platDate,jdbcType=VARCHAR},'yyyy-mm-dd') ) )

SELECT FINPROD_ID id, FINPROD_ABBR||':'||FINPROD_MARKET_ID text FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND ( FIN_PRODUCT.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND FINPROD_ID = #{initValue}
AND FINPROD_ID NOT IN( SELECT O_FINPROD_ID FROM FIN_PRODUCT WHERE O_FINPROD_ID IS NOT NULL )

SELECT count(1)
FROM FIN_PRODUCT
WHERE O_FINPROD_ID = #{oFinprodId}
and FINPROD_ID != #{finprodId}
